import { randomUUID } from "node:crypto";
import { Client } from "pg";

const databaseUrl = process.env.TEST_DATABASE_URL;
// Committed rows are necessary for visibility across connections. Opt in only
// on loopback, and delete only IDs generated by this suite. All competing
// operations/locks roll back; no worker is invoked with committed fixtures.
const isLocal = databaseUrl && ["localhost", "127.0.0.1", "[::1]"].includes(new URL(databaseUrl).hostname);
const describeLocal = isLocal ? describe : describe.skip;

describeLocal.each(["need", "resource"] as const)("campaign %s shared-parent locking", kind => {
  let fixture: Client;
  let blocker: Client;
  let contender: Client;
  let owner: string;
  let campaignOwner: string;
  let listing: string;
  let campaign: string;
  let submission: string;

  async function identity(client: Client, account: string) {
    await client.query("set local role identified_account");
    await client.query("select set_config('jwt.claims.account_id',$1,true),set_config('jwt.claims.role','identified_account',true)", [account]);
  }

  beforeEach(async () => {
    fixture = new Client({ connectionString: databaseUrl });
    blocker = new Client({ connectionString: databaseUrl });
    contender = new Client({ connectionString: databaseUrl });
    await fixture.connect();
    await blocker.connect();
    await contender.connect();
    await fixture.query("begin");
    [owner, campaignOwner] = (await fixture.query(`insert into app_public.account(external_subject)
      values($1),($2) returning id`, [`lock-owner-${randomUUID()}@example.com`, `lock-campaign-${randomUUID()}@example.com`])).rows.map(row => row.id);
    listing = (await fixture.query(`insert into app_public.${kind}(creator_account_id,title,location,intensity)
      values($1,'Parent lock fixture','Test','sharing') returning id`, [owner])).rows[0].id;
    campaign = (await fixture.query(`insert into app_public.campaign(creator_account_id,title,theme,rewards_multiplier,
      airdrop_amount,start_at,airdrop_at,end_at,moderation_status) values($1,'Parent lock fixture','test',5,3000,
      now()-interval '3 days',now()+interval '1 day',now()+interval '3 days','approved') returning id`, [campaignOwner])).rows[0].id;
    await identity(fixture, owner);
    submission = (await fixture.query(`select submission_id from app_public.link_campaign_${kind}($1,$2)`, [campaign, listing])).rows[0].submission_id;
    await fixture.query("commit");
  });

  afterEach(async () => {
    try {
      // Always release both sessions before cleanup, including assertion failure.
      await blocker?.query("rollback");
      await contender?.query("rollback");
      await fixture?.query("rollback");
      await fixture?.query("reset role");
      await fixture?.query("begin");
      await fixture?.query("set local lock_timeout='2s'");
      if (campaign) await fixture.query("delete from app_public.campaign where id=$1", [campaign]);
      if (listing) await fixture.query(`delete from app_public.${kind} where id=$1`, [listing]);
      if (owner && campaignOwner) await fixture.query("delete from app_public.account where id=any($1::uuid[])", [[owner, campaignOwner]]);
      await fixture?.query("commit");
    } finally {
      await Promise.all([fixture?.end(), blocker?.end(), contender?.end()]);
    }
  });

  it.each(["link", "accept", "reject"] as const)("%s waits for the listing parent, then succeeds after lock rollback", async action => {
    await blocker.query("begin");
    // This is the ONLY row locked by the other session: a timeout therefore
    // proves all three entry points serialize on the same listing parent.
    await blocker.query(`select id from app_public.${kind} where id=$1 for update`, [listing]);
    await contender.query("begin");
    await contender.query("set local lock_timeout='150ms'");
    await identity(contender, action === "link" ? owner : campaignOwner);
    const sql = `select * from app_public.${action}_campaign_${kind}($1,$2${action === "link" ? "" : ",$3"})`;
    const values = action === "link" ? [campaign, listing] : [campaign, listing, submission];
    await expect(contender.query(sql, values)).rejects.toMatchObject({ code: "55P03" });
    await contender.query("rollback");
    await blocker.query("rollback");
    await contender.query("begin");
    await contender.query("set local lock_timeout='2s'");
    await identity(contender, action === "link" ? owner : campaignOwner);
    const result = await contender.query(sql, values);
    expect(result.rows[0]).toMatchObject({ submission_id: submission,
      status: action === "link" ? "pending" : action === "accept" ? "accepted" : "rejected" });
    await contender.query("rollback");
    expect((await fixture.query(`select status,is_current from app_public.campaign_${kind}
      where campaign_id=$1 and ${kind}_id=$2`, [campaign, listing])).rows).toEqual([{ status: "pending", is_current: true }]);
  });
});